<template><section class="module-view">
  <div class="tabs"><button v-for="item in ['Volcano','Heatmap','Gene table','Source']" :key="item" :aria-pressed="view===item" @click="view=item;loadHeatmap()">{{item}}</button></div>
  <div class="module-stage"><div class="controls"><label>Dataset <select v-model="selected" @change="load"><option v-for="(item,i) in catalogue" :key="item.asset" :value="i">{{item.dataset}} · {{item.label}}</option></select></label></div>
  <p v-if="error" role="alert">{{error}} <button @click="load">Retry</button></p><p v-if="busy" role="status">Loading selected comparison…</p>
  <template v-if="data"><p class="source">{{data.dataset}} · {{data.label}} · {{data.rows.length.toLocaleString()}} source gene records</p>
    <div v-if="view==='Volcano'"><ScatterPlot :rows="points" x-label="log₂ fold change" y-label="−log₁₀ adjusted P" title="Differential-expression"/><details class="plot-settings"><summary>Highlight and thresholds</summary><div class="controls"><label>Absolute log₂ fold-change <input type="number" v-model.number="fold" min="0" step="0.1"/></label><label>Adjusted P threshold <input type="number" v-model.number="pvalue" min="0.000000000001" max="1" step="0.01"/></label><label>Highlight gene <input v-model="gene" maxlength="80"/></label></div></details><p class="source">Red: positive fold change; blue: negative fold change, passing both thresholds. Orange: selected gene. This is a cohort comparison, not a temporal trajectory.</p></div>
    <div v-if="view==='Heatmap'"><p v-if="heatError" role="alert">{{heatError}} <button @click="loadHeatmap(true)">Retry heatmap</button></p><p v-else-if="!heat" role="status">Loading source-selected genes…</p><div v-else><p>Source-selected top genes · Z-normalized expression · Source sample order</p><div class="heatmap-scroll"><table class="heatmap"><tbody><tr v-for="row in heat" :key="row.gene"><th>{{row.gene}}</th><td v-for="(value,i) in row.expression" :key="i" :style="{background:heatColor(value)}" :title="`${row.gene}, source sample ${i+1}: ${value}`"/></tr></tbody></table></div><p class="source">Blue: lower relative expression; white: zero; red: higher. Colors saturate at z = −3 and +3. Per-gene z scores do not measure absolute expression. Sample metadata remains in the source dataset.</p></div></div>
    <div v-if="view==='Gene table'"><div class="controls"><label>Find gene <input v-model="search"/></label><label>Sort <select v-model="sort"><option value="p">Adjusted P</option><option value="fold">Absolute fold change</option><option value="gene">Gene</option></select></label></div><table><thead><tr><th>Gene</th><th>log₂ fold change</th><th>−log₁₀ adjusted P</th></tr></thead><tbody><tr v-for="row in tableRows.slice(page*50,(page+1)*50)" :key="row[0]"><td><button @click="gene=row[0];view='Volcano'">{{row[0]}}</button></td><td>{{row[1]??'Not reported'}}</td><td>{{row[2]??'Not reported'}}</td></tr></tbody></table><button :disabled="page===0" @click="page--">Previous</button><span> {{page+1}} / {{Math.max(1,Math.ceil(tableRows.length/50))}} </span><button :disabled="(page+1)*50>=tableRows.length" @click="page++">Next</button></div>
    <div class="controls"><button @click="download">Download comparison</button><a :href="data.source.url" target="_blank" rel="noopener">Original source table ↗</a></div>
    <div v-if="view==='Source'" class="source-panel"><h2>Source &amp; methods</h2><p>The complete source comparison is retained. Dataset and comparison columns are stored once; numeric values are not rounded. Non-numeric source statistics remain missing. The heatmap is retrieved only when its tab is opened.</p><p>Source SHA-256: {{data.source.sha256}}</p></div>
  </template></div></section></template>
<script>
import { interpolateRdBu } from 'd3';
import { localJson, downloadText } from './assets.mjs';
import { assetUrl } from './source.mjs';
import { readBioIndex } from './data.mjs';
import ScatterPlot from './ScatterPlot.vue';
export default { components:{ScatterPlot},props:['context'],data:()=>({catalogue:[],selected:0,data:null,busy:false,error:'',gene:'',view:'Volcano',fold:1.5,pvalue:0.05,search:'',sort:'p',page:0,heat:null,heatError:'',heatPending:false,serial:0}),
  computed:{points(){return this.data.rows.map(([name,x,y])=>({x,y,label:name,highlight:name===this.gene,color:name===this.gene?'#f59e0b':Math.abs(x)>this.fold&&y>-Math.log10(this.pvalue)?x>0?'#bf2c23':'#2f67b1':'#94a3b8'}));},tableRows(){const rows=this.data.rows.filter(r=>r[0].toLowerCase().includes(this.search.toLowerCase()));return rows.sort((a,b)=>this.sort==='gene'?a[0].localeCompare(b[0]):this.sort==='fold'?Math.abs(b[1]??0)-Math.abs(a[1]??0):(b[2]??-Infinity)-(a[2]??-Infinity));}},
  watch:{search(){this.page=0;},sort(){this.page=0;}},
  async mounted(){this.gene=this.context.geneSymbol||'';await this.load();},
  methods:{async load(){const token=++this.serial;this.error='';this.busy=true;this.data=null;this.heat=null;this.heatPending=false;this.heatError='';this.page=0;try{if(!this.catalogue.length){this.catalogue=(await localJson('data/manifest.json')).de;const exact=this.catalogue.findIndex(x=>x.dataset===this.context.datasetId);const related=this.catalogue.findIndex(x=>x.dataset.split('_').pop().toLowerCase()===(this.context.cellType||'').replaceAll(' ','').toLowerCase());this.selected=exact>=0?exact:related>=0?related:0;}const data=await localJson('data/'+this.catalogue[this.selected].asset);if(token===this.serial){this.data=data;this.loadHeatmap();}}catch(e){if(token===this.serial)this.error=e.message;}finally{if(token===this.serial)this.busy=false;}},async loadHeatmap(retry=false){if(!this.data||this.view!=='Heatmap'||this.heat||this.heatPending)return;const token=this.serial;this.heatPending=true;this.heatError='';try{const response=await readBioIndex(assetUrl('supplement/heatmaps/'+this.data.dataset+'.json'));if(token!==this.serial)return;if(!Array.isArray(response.data)||!response.data.every(r=>r.dataset===this.data.dataset&&r.comparison===this.data.label&&Array.isArray(r.expression)))throw new Error('Heatmap context does not match the selected comparison.');if(token===this.serial)this.heat=response.data;}catch(e){if(token===this.serial)this.heatError=e.message;}finally{if(token===this.serial)this.heatPending=false;}},heatColor(value){return Number.isFinite(value)?interpolateRdBu(0.5-Math.max(-3,Math.min(3,value))/6):'#e2e8f0';},download(){downloadText(['dataset\tcomparison\tgene\tlogFoldChange\t-log10P',...this.data.rows.map(r=>[this.data.dataset,this.data.label,...r.map(v=>v??'NA')].join('\t'))].join('\n'),this.data.dataset+'-'+this.data.comparison+'.tsv');}},
};
</script>
